import sys

s = sys.stdin.read().split()[0]
n = len(s)
total = 0
for i in range(n):
    if s[i] == '0':
        continue
    for j in range(i + 1, n + 1):
        v = int(s[i:j])
        if v & (v - 1) == 0 and v <= 2 ** 60:
            total += 1
print(total)

